(3433,1095,'_form','<div class=\"row\">\n  <div class=\"col-md-4\">\n    <div class=\"form-group\">\n      <label class=\"control-label\">Default Input</label>\n      [text text-default class:form-control placeholder \"Your placeholder text...\"]\n    </div>\n    <div class=\"form-group\">\n      <label class=\"control-label\">Disabled Input</label>\n      [text text-disabled readonly class:form-control placeholder \"Your placeholder text...\"]\n    </div>\n    <div class=\"form-group\">\n      <label class=\"control-label\">Select Input</label>\n      [select menu-select class:form-control \"Canada\" \"Italy\" \"Spain\" \"Greece\"]\n    </div>\n  </div>\n  <div class=\"col-md-4\">\n    <div class=\"form-group\">\n      <label class=\"control-label\">Textarea</label>\n      [textarea textarea-default class:form-control placeholder \"Your placeholder text...\"]\n    </div>\n  </div>\n  <div class=\"col-md-4\">\n    <h6>Checkboxes</h6>\n    <div class=\"form-group\">\n      [checkbox checkbox-default use_label_element \"Option 1\" \"Option 2\" \"Option 3\"]\n    </div>\n\n    <h6>Radio Buttons</h6>\n    <div class=\"form-group\">\n      [radio radio-default use_label_element default:1 \"Option 1\" \"Option 2\" \"Option 3\"]\n    </div>\n  </div>\n</div>'),
